from dec1 import d, D
# Aristóteles
for i in ['d05','d06','d18','d01','d02','d14','d07','d08','d09','d19','d20','d21','d10','d11','d12','d22','d23','d24','d13']: d('aristoteles-'+i,'A')
d('aristoteles-d16','R')
d('aristoteles-d17','A pergunta está mal posta: o mundo é eterno, nunca começou e nunca vai acabar. O que pede explicação é o seu movimento eterno.','I')
d('aristoteles-d15','Zenão diz que, para chegar ao fim da pista, você teria de passar por infinitas metades. Mas a pista não está cortada em pedaços: pode ser dividida sem fim, e a corrida é uma só, contínua.','P')
# Platão
for i in ['d04','d05','d06','d16','d18','d01','d02','d03','d13','d14','d15','d07','d09','d19','d20','d10','d11','d12','d22','d23','d24']: d('platao-'+i,'A')
d('platao-d08','A','T')
d('platao-d21','Protágoras diz que o homem é a medida de todas as coisas. Eu digo: a medida é o divino. E o justo não é o que convém ao mais forte, como queria Trasímaco.','P','Leis IV, 716c; República I, 338c–339a')
# Sócrates
for i in ['d16','d18','d07','d08','d20','d10','d11','d22','d24']: d('socrates-'+i,'A')
d('socrates-d04','Dizem que não creio nos deuses. Mas foi o deus que me deu a missão de examinar Atenas, e desde menino ouço uma voz divina que me detém.','P','Platão, Apologia 23b e 31c–d')
d('socrates-d05','A morte é só a alma se separando do corpo, e a alma não morre. Então parem de chorar, amigos.','P','Platão, Fédon 64c e 117c–e')
d('socrates-d06','Ninguém erra de propósito: quem faz o mal se engana sobre o que é bom para si. Quem conhece o bem o pratica.','I')
d('socrates-d17','Sei que nada sei, e essa pergunta está muito além do pouco que sei. Prefiro confessar a ignorância a fingir uma resposta.','I')
d('socrates-d01','Investigar a natureza só me deixou confuso. Prefiro as questões humanas: conhecer a mim mesmo importa mais que conhecer o universo.','P','Platão, Fédon 96a–99d; Xenofonte, Memoráveis I, 1, 11–16')
d('socrates-d02','Geometria? Até saber medir um terreno. Especular sobre como o deus arranjou o céu já é vaidade.','P','Xenofonte, Memoráveis IV, 7, 2–6')
d('socrates-d03','Sou como minha mãe, que era parteira: não tenho sabedoria própria, mas ajudo os outros a dar à luz ideias. Depois examino se a criança respira.','P','Platão, Teeteto 149a–151d')
d('socrates-d14','Olhos para ver, pálpebras que se fecham como portas para protegê-los. Tanta adequação não pode ser obra do acaso.','P','Xenofonte, Memoráveis I, 4, 5–7')
d('socrates-d15','Dizem que conversar comigo é como tocar numa arraia elétrica: dá um branco. Aceito, desde que a arraia também fique atordoada. É da perplexidade que a busca recomeça.','P','Platão, Mênon 80a–d')
d('socrates-d09','Converso com qualquer um: sapateiros, generais, escravos. Um menino escravo, sem estudo, resolveu comigo um problema de geometria. Diante da razão, todos podem aprender.','I','Platão, Apologia 33a–b; Mênon 82b–85b')
d('socrates-d19','Fugir da prisão? Imaginei as Leis de Atenas me perguntando: depois de setenta anos sob nós, vai nos destruir por causa de uma sentença injusta?','P','Platão, Críton 50a–54d')
d('socrates-d21','Os deuses amam o piedoso porque ele é piedoso, ou ele é piedoso porque os deuses o amam? Se for a primeira, a moral não depende da vontade de ninguém.','P','Platão, Eutífron 10a–11b')
d('socrates-d12','A razão deve governar os desejos. Eu aguento frio, fome e vinho sem perder o domínio de mim. Alcibíades que o diga.','P','Platão, Banquete 219e–220d; Xenofonte, Memoráveis I, 2, 1')
d('socrates-d23','Perguntei aos poetas o que queriam dizer com seus versos. Não souberam explicar: compõem por inspiração, como adivinhos, não por sabedoria.','P','Platão, Apologia 22a–c')
# Epicuro
for i in ['d04','d05','d06','d16','d18','d01','d03','d13','d15','d08','d09','d19','d20','d21','d10','d11','d12','d22','d24']: d('epicuro-'+i,'A')
d('epicuro-d17','A','P')
d('epicuro-d02','Não: o mundo é feito de átomos que se chocam e às vezes se desviam. A geometria abstrata ajuda pouco a entender a natureza, e menos ainda a viver bem.','I')
d('epicuro-d14','Nada nasce do nada, e nada volta ao nada. Mas os átomos às vezes dão um pequeno desvio, e a cadeia rígida das causas se quebra.','P','Carta a Heródoto 38–39; Lucrécio, Da Natureza das Coisas II, 216–293')
d('epicuro-d07','A','T')
d('epicuro-d23','A arte vale enquanto dá um prazer sereno, como uma boa conversa entre amigos. Usá-la para buscar fama é criar um desejo que não acaba.','I')
# Pitágoras
for i in ['d04','d05','d16','d17','d18','d01','d02','d03','d13','d14','d15','d07','d08','d09','d21','d10','d11','d12','d23','d24']: d('pitagoras-'+i,'A')
d('pitagoras-d06','A alma está presa à roda dos renascimentos, mas pode se libertar pela purificação. Liberdade não é ponto de partida: é disciplina.','I')
d('pitagoras-d19','R')
d('pitagoras-d22','A alma quer voltar à harmonia de que se afastou ao nascer. Viver bem é reafinar-se.','I')
# Nietzsche
for i in ['d04','d05','d06','d16','d18','d02','d03','d13','d14','d07','d09','d19','d20','d21','d10','d11','d12','d22','d23']: d('nietzsche-'+i,'A')
d('nietzsche-d17','A','P')
d('nietzsche-d08','A democracia moderna é herdeira da moral de rebanho: nivela todos. Desconfio de todo Estado e de toda massa.','P')
# Diógenes (restantes, em primeira pessoa)
d('diogenes-d02','Os matemáticos vivem olhando o sol e a lua, e não enxergam o que está aos seus pés.','P')
d('diogenes-d08','Perguntam de onde sou: sou cidadão do mundo. E os políticos que vivem de agradar à multidão? Criados dela.','P','Diógenes Laércio VI, 24 e 63')
d('diogenes-d09','Quando me puseram à venda como escravo, mandei o pregoeiro anunciar: quem quer comprar um senhor?','P','Diógenes Laércio VI, 29 e 74')
d('diogenes-d19','A única cidade de verdade é o mundo. As cidades humanas, com suas leis e costumes, são convenções, e eu vivo nelas como um cão: em público.','P')
d('diogenes-d20','Comer na praça é indecente? Senti fome na praça, então comi na praça. Mal é seguir costumes vazios.','I','Diógenes Laércio VI, 58 e 69')
d('diogenes-d21','Dizem que falsifiquei moeda. Pois continuo: tiro de circulação os valores da cidade e ponho os da natureza.','P')
d('diogenes-d10','Vi um rapaz bonito estudando filosofia e o elogiei: assim seus admiradores trocam a beleza do corpo pela da alma.','P')
d('diogenes-d11','A paixão amorosa? Ocupação de quem não tem o que fazer.','P','Diógenes Laércio VI, 51')
d('diogenes-d12','No inverno, abraço estátuas geladas; no verão, rolo na areia quente. Corpo treinado, ânimo firme.','P')
d('diogenes-d22','Vi um rato correndo por aí: não procura cama, não tem medo do escuro, não quer luxo. Aprendi com ele a viver.','P')
d('diogenes-d23','A arte que importa é a de viver: mostrar com a própria vida o que se ensina. O resto é enfeite.','I',None,2,'A revisão lembra que Diógenes usava poetas para ensinar os filhos de Xeníades; "o resto é enfeite" talvez exagere.')
d('diogenes-d24','Todo mundo se esforça para pular mais longe e correr mais rápido. Ninguém se esforça para ser bom.','P')
